const NAS_BASE_PATH = '/home/node/n8n-files/projects';

const input = $input.first().json;
const projectId = input.formQueryParameters?.project_id || '';
const folderPath = input.formQueryParameters?.folder_path || '';

if (!projectId || !folderPath) {
  throw new Error('Geen project_id of folder_path opgegeven.');
}

// Beveiligingscheck
if (folderPath.includes('..') || folderPath.startsWith('/')) {
  throw new Error('Ongeldig pad.');
}

const targetDir = `${NAS_BASE_PATH}/${projectId}/${folderPath}`;

return [{ json: { projectId, folderPath, targetDir } }];

// Verplaats geüploade bestanden naar de doelmap
const setup = $('Setup').first().json;
const formData = $('Form Trigger').first();
const files = formData.binary || {};
const targetDir = setup.targetDir;

const commands = [];
let fileCount = 0;

for (const [key, fileInfo] of Object.entries(files)) {
  if (fileInfo.fileName) {
    // n8n slaat uploads tijdelijk op, we moeten ze kopiëren
    commands.push({
      fileName: fileInfo.fileName,
      mimeType: fileInfo.mimeType,
      key
    });
    fileCount++;
  }
}

return [{ json: { targetDir, fileCount, files: commands } }];
